Definition is_leaf (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : Prop :=
  exists tags, nth_error CPS i = Some c /\ nth_error TAGS i = Some tags /\ nth_error (CC.cp_PSS c) k = Some ps /\ nth_error tags k = Some t.

