  0 <= a < 2 ^ 64 /\ ((sp0 <= a < hl_sptop L) \/ (hl_img_lo L <= a < hl_img_hi L /\ ~ hl_alloc_static L a /\ ~ hl_alloc_ro L a /\ ~ in_errno L a)).
