Lemma blocks_facts : forall LBown cr M VM, hi_heap HI (LBown ++ LBrest) cr M VM ->
  (forall b, In b (LBown ++ LBrest) -> block_range L (fst b) (snd b) /\ HeapIface.defined M (fst b) (snd b))
