Lemma survive_know : forall E M M' BL kn c ks, env_agree NF E0 E -> blocks_in_range (den E BL ++ LBrest) ->
  c <= 0 -> - SCR <= c - hl_stack L ->
  know_ok (hl_segs L) E M kn -> know_ok (hl_segs L) E M ks -> forallb (CH.survive_chk d kn c BL) ks = true ->
  heap_pres_core L (den E BL ++ LBrest) (sp0 + c) M M' ->
  know_ok (hl_segs L) E M' ks.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S:0|30;%~R!1+4!1,5|600;!1+3!1+4!1,50!1+8+b4!2+9+I+I!1'aU/L;!4'c@/d;#=#<#>%x;R+b4%~R!3'M+b4#1#<!3+2+A!5'c@/d;#?#>#@#2,G!3'M+b4#1#=!3'bY4#B#A%x;R+b4%~R7!4'bY4#D#C#2$E;R+>$M;R1$M';R1$BL;R'`7$kn;R2$c;R+I$ks;R2$Hag;R!3'@/NF;/E0;#7$HH;R!1'bS!3'^63!2'V#8#5/LBrest;$Hc;R!2'^Z#4,^[$Hc2;R!2'^Z!1'bO!1'`>/d;!2'`E#5!1'aF/L;$Hkn;R!4'b54#;#:#7$Hks;R!4'b54#<#;#6$Hall;R!3+2+A!3'B+b4!4'c@/d;#9#8#:#7,G$Hp;R!5'aI/L;!3'^63!2'V#>#;/LBrest;!2'^N/sp0;#9#=#<!:'cJ/L;!3'^63!2'V#?#</LBrest;!2'^N/sp0;#:#?#>#=#9#1$X;R+b4$HX;R!3'M+b4#1#:&Hall;R!2$lemma;R!2'N!3+2+A!3'B+b45#;,G6!3'O!3+2+A!3'B+b4!4'c@/d;#>#=#?#<,G%x;R+b4%~R7!3+2+A!5'c@/d;#@#?#A#2,G#1!3'P+b45#;#46&Hks;R!2$lemma;R!2'N!3+cK+b48#<9!3'O!3+cK+b4!3'bY4#C#B#=%x;R+b4%~R!3'M+b4#1#>!4'bY4#E#D#2#1!3'cL+b48#<#69!='cM#C#B#@#?#>#4#<#;#:#9#8!2#1#4#3!2#2#4#3#3").
