Definition blocks_vars_lt (b : nat) (BL : CA.blocks) : bool :=
  forallb (fun x : expr * expr => (APC.expr_vars_lt b (fst x) && APC.expr_vars_lt b (snd x))%bool) BL.
Definition foot_chk (c : CC.cutpoint) (BL : CA.blocks) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S30!2+9+?+I!1'cO#2!1'cP#2$c;R+^@$BL;R'`7!2'C!2'C!2'C!3'B'aZ$r;R'aZ-9RN$r;R!2+90+?+A#11$p;R0$rlen;R+?-9RN$p;R!2+9+?+I+A#21$rb;R+?$rlo;R+I!5'b6!1'cN#7!2'bJ/d;#6#2#1#31!3'B'aZ!1'a[21!2'cQ2#1!2'cR/NF;2").

Lemma foot_chk_sound : forall c BL E E' R M (a : word),
