Definition retE (E' : env) (nx : nat) (R2 : bvmap 5 word) : env := ltac2:(Rpl.RP.run_i (rplG ()) 3 "S20!1,5|21;!1+4!1,5|600;$E';R+>$nx;R+=$R2;R!2'cS01!3'fI#3#2!4'Y+=1$r;R+=!2'dM#2!2'`?0!1'^O#1'fE").

Lemma ret_regs : forall E' regs nx (R' R2 : bvmap 5 word),
  regs_ok E' regs R' -> APC.sr_vars_lt nx regs = true ->
