Variable TAGS : list (list CC.tag).
Variable RETS : list (nat * nat * nat * Z).      (* [comment removed for export] *)
Variable MALLOC FREE : Z.
Variable COPIES : list Z.                        (* [comment removed for export] *)
Local Abbreviation is_leaf := (CH2.is_leaf CPS TAGS).

Definition ret_of (i k : nat) : option nat := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S40!2+9+=+=!2+90+=!2+91+I!1+3+=$i;R+=$k;R+=-3RN$x;R!1+323!3'e42$r;R2-9RN$r;R!2+91+I+A#11$p;R1$z;R+I-9RN$p;R!2+90+=+A#21$p0;R0$k';R+=-9RN$p0;R!2+9+=+=+A#21$n;R+=$i';R+=!2'C!2'dG#9#1!2'dG#8#3/RETS;2$p;R2-9RN$p;R!2+91+I3#11$p0;R1$z;R+I-9RN$p0;R!2+90+=3#21$p1;R0$n;R+=-9RN$p1;R!2+9+=+=3#21$j;R+=$n0;R+=!2,^E+=#2!1,7+=").
Definition is_call (pc : Z) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S00$pc;R+I!2'fF!2'fF!2'^1#1/MALLOC;!2'^1#1/FREE;!3'b3+I!1'^1#1/COPIES;").
Definition leaf_chk (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 5 "S30!1,;!2+9+?+?!4'`6'`7#2/BLS;0!4'`6'`7#8/BLS;0$i;R+=$c;R+^@$k;R+=$ps;R+^A$t;R+^B-^BRN$t;R+^B+A#12$j;R+=$s;R'd6!4'd=#6!4'`6'`7#7/BLS;01#1$pc;R+I-ARN$~R+A+A!1'h\#12-3RN$x;R!1+3+=+A!2'i0#6#42$j;R+=-3RN$x;R!1+3+^@+A!3'^D+^@/CPS;#12$cj;R+^@-ARN$~R+A+A!2'^1#3/MALLOC;2!6'g;/MALLOC;#7#5#121-ARN$~R+A+A!2'^1#3/FREE;2!6'g[/FREE;#7#5#121!6'hM#3#7#5#121,b>,b>!2'cT#5!4'`6'`7#6/BLS;0").
Definition heap_chk : bool := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!3'i1/CPS;/TAGS;'i2").
Lemma heap_chk_sound : heap_chk = true -> forall i c tags k ps t,
  nth_error CPS i = Some c -> nth_error TAGS i = Some tags -> nth_error (CC.cp_PSS c) k = Some ps -> nth_error tags k = Some t ->
  leaf_chk i c k ps t = true.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!3'i3/CPS;/TAGS;'i2").
Qed.

